@deterministic
fn steer(pos: Vec3, target: Vec3, speed: f32) -> Vec3:
    dir = (target - pos).normalize()       # one sqrt: the same bits on every machine
    boost = cbrt(speed)                    # C's cbrtf: its last bit differs between C libraries
    return dir * (speed * boost)

