fn inv_lengths(xs: Span[f32], ref mut out: MutSpan[f32]):
    for i in range(0, xs.len(), 8):
        v = f32x8.load(xs[i..i + 8])
        v.rsqrt_approx().store(ref mut out[i..i + 8])   # a hardware estimate: differs between CPU makers

