from std.ffi import ForeignCallback, Retained

class Hud:
    clicks: i32 = 0

unsafe extern "C":
    @safety("`cb` and `ud` are a pair `on_click` was given")
    unsafe fn off_click(cb: extern "C" fn(*mut void), ud: *mut void)
    @ffi(param(cb, callback(retained, user_data=ud), threads(creator)), destroys(off_click))
    safe fn on_click(owns cb: fn(), ud: *mut void) -> Retained[ForeignCallback]   # spelled as recommended in J8-01

fn main():
    hud = shares mut Hud()
    tokens: Array[Retained[ForeignCallback]] = []
    for i in 0..70000:
        tokens.push(owns on_click(owns fn() shares mut hud: hud.clicks += 1))   # on a 32-bit target, slot 65,537 does not exist
    println(tokens.len())
